# log-processing-pipeline.yaml
apiVersion: v1
kind: ConfigMap
metadata:
  name: log-processing-pipeline
  namespace: logging
data:
  pipeline.conf: |
    input {
      beats {
        port => 5044
        ssl => true
        ssl_certificate => "/etc/pki/tls/certs/logstash.crt"
        ssl_key => "/etc/pki/tls/private/logstash.key"
      }
    }

    filter {
      # 标准化时间戳
      date {
        match => [ "timestamp", "ISO8601" ]
        target => "@timestamp"
        remove_field => [ "timestamp" ]
      }

      # 解析JSON消息体
      json {
        source => "message"
        skip_on_invalid_json => true
      }

      # 标准化日志级别
      mutate {
        lowercase => [ "log.level" ]
        convert => {
          "http.response.status_code" => "integer"
          "http.request.duration" => "float"
        }
      }

      # 添加环境标识
      mutate {
        add_field => {
          "[fields][environment]" => "%{[@metadata][beat]}"
          "[fields][service]" => "%{[kubernetes][container][name]}"
        }
      }

      # IP地理位置解析
      geoip {
        source => "[client][ip]"
        target => "client_geo"
        database => "/usr/share/GeoIP/GeoLite2-City.mmdb"
      }

      # 用户代理解析
      useragent {
        source => "[http][request][headers][user-agent]"
        target => "user_agent"
        regexes => "/etc/logstash/regexes.yaml"
      }

      # 数据脱敏处理
      if [message] =~ /password|secret|token/i {
        mutate {
          gsub => [
            "message", "(password|secret|token)[=:][^&\s]+", "\\1=***MASKED***"
          ]
        }
      }
    }

    output {
      elasticsearch {
        hosts => ["https://elasticsearch:9200"]
        index => "logs-%{[@metadata][beat]}-%{+YYYY.MM.dd}"
        user => "${ELASTICSEARCH_USERNAME}"
        password => "${ELASTICSEARCH_PASSWORD}"
        ssl_certificate_verification => true
        ilm_enabled => true
        ilm_rollover_alias => "logs-%{[@metadata][beat]}"
        ilm_pattern => "{now/d}-000001"
        ilm_policy => "logs-policy"
      }
    }

# ilm-policies.yaml
apiVersion: v1
kind: ConfigMap
metadata:
  name: ilm-policies
  namespace: logging
data:
  application-logs-policy.json: |
    {
      "policy": {
        "phases": {
          "hot": {
            "actions": {
              "rollover": {
                "max_age": "7d",
                "max_size": "50gb",
                "max_docs": 10000000
              },
              "set_priority": {
                "priority": 100
              }
            }
          },
          "warm": {
            "min_age": "7d",
            "actions": {
              "allocate": {
                "number_of_replicas": 1,
                "include": {},
                "exclude": {
                  "box_type": "hot"
                }
              },
              "forcemerge": {
                "max_num_segments": 1
              },
              "set_priority": {
                "priority": 50
              }
            }
          },
          "cold": {
            "min_age": "30d",
            "actions": {
              "allocate": {
                "number_of_replicas": 0,
                "require": {
                  "box_type": "cold"
                },
                "include": {},
                "exclude": {}
              },
              "freeze": {},
              "set_priority": {
                "priority": 0
              }
            }
          },
          "delete": {
            "min_age": "365d",
