apiVersion: v1
kind: ConfigMap
metadata:
  name: ml-anomaly-jobs
  namespace: logging
data:
  http-response-codes.json: |
    {
      "job_id": "http_response_codes_analysis",
      "job_type": "anomaly_detector",
      "description": "HTTP响应码异常检测",
      "analysis_config": {
        "bucket_span": "15m",
        "detectors": [
          {
            "detector_description": "异常HTTP错误率",
            "function": "high_count",
            "by_field_name": "http.response.status_code",
            "partition_field_name": "kubernetes.namespace"
          }
        ],
        "influencers": [
          "kubernetes.namespace",
          "kubernetes.pod.name",
          "host.name"
        ]
      },
      "data_description": {
        "time_field": "@timestamp",
        "time_format": "epoch_ms"
      },
      "model_plot_config": {
        "enabled": true,
        "annotations_enabled": true
      },
      "analysis_limits": {
        "model_memory_limit": "1GB",
        "categorization_examples_limit": 4
      },
      "datafeed_config": {
        "datafeed_id": "datafeed-http_response_codes_analysis",
        "indices": ["filebeat-*"],
        "scroll_size": 1000,
        "delayed_data_check_config": {
          "enabled": true
        },
        "query": {
          "bool": {
            "filter": [
              {
                "exists": {
                  "field": "http.response.status_code"
                }
              },
              {
                "range": {
                  "http.response.status_code": {
                    "gte": 400
                  }
                }
              }
            ]
          }
        }
      }
    }

  log-volume-anomaly.json: |
