        ],
        "influencers": [
          "kubernetes.container.name",
          "kubernetes.namespace"
        ]
      },
      "data_description": {
        "time_field": "@timestamp"
      },
      "model_plot_config": {
        "enabled": true
      },
      "analysis_limits": {
        "model_memory_limit": "512MB"
      },
      "datafeed_config": {
        "datafeed_id": "datafeed-log_volume_anomaly_detection",
        "indices": ["filebeat-*"],
        "query_delay": "60s",
        "frequency": "150s",
        "query": {
          "match_all": {}
        }
